-- Drag window
local dragging, dragStart, startPos
local function updateDrag(input)
    local delta = input.Position - dragStart
    frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
    shadow.Position = frame.Position
end
frame.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 then
        dragging = true
        dragStart = input.Position
        startPos = frame.Position
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then dragging = false end
        end)
    end
end)
UIS.InputChanged:Connect(function(input)
    if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then updateDrag(input) end
end)

box.Focused:Connect(function()
    boxStroke.Color = Color3.fromRGB(255, 204, 45)
end)
box.FocusLost:Connect(function()
    boxStroke.Color = Color3.fromRGB(55, 55, 55)
end)

local unlocked = false
local busy = false
local API_URL = "https://tvlgqctztgdpyxeoeeaj.supabase.co/functions/v1/redeem-key"
local SAVE_FILE = "Lightning_Redeemer_Auth.token"
local HttpService = game:GetService("HttpService")

local function getRequest()
    return (syn and syn.request) or (http and http.request) or request or http_request
end

local function readToken()
    if type(isfile) == "function" and type(readfile) == "function" and isfile(SAVE_FILE) then
        local ok, value = pcall(readfile, SAVE_FILE)
        if ok and value and #value > 0 then return value:gsub("%s+$", "") end
    end
end

local function saveToken(token)
    if type(writefile) == "function" then pcall(writefile, SAVE_FILE, token) end
end

local function serverCall(path, body)
    local req = getRequest()
    if not req then
        return false, "executor does not provide HTTP requests"
    end

    local ok, res = pcall(req, {
        Url = API_URL,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = HttpService:JSONEncode(body),
    })

    if not ok or not res then
        return false, "request failed"
    end

    local statusCode = res.StatusCode or res.Status or 0

    local decoded = nil
    pcall(function()
        decoded = HttpService:JSONDecode(res.Body or "{}")
    end)

    if statusCode >= 200 and statusCode < 300 and decoded then
        return true, decoded
    end

    return false, (decoded and decoded.error) or "unauthorized"
end

local function redeem()
    if busy then return end
    local key = box.Text:gsub("^%s+", ""):gsub("%s+$", "")
    if key == "" then
        status.Text = "Enter a key first."
        status.TextColor3 = Color3.fromRGB(255, 180, 70)
        return
    end
    busy = true
    status.Text = "Checking key..."
    status.TextColor3 = Color3.fromRGB(255, 204, 45)
    local ok, data = serverCall("/redeem", {
    action = "redeem",
    key = key,
    userId = tostring(game.Players.LocalPlayer.UserId)
})
    if ok and data.ok and data.token then
        saveToken(data.token)
        status.Text = "Key redeemed • Loading..."
        status.TextColor3 = Color3.fromRGB(130, 255, 150)
        task.wait(0.25)
        finish()
    else
        busy = false
        if data == "already_redeemed" then
            status.Text = "This key has already been redeemed."
        elseif data == "invalid_key" then
            status.Text = "Invalid key."
        else
            status.Text = "Authorization failed."
        end
        status.TextColor3 = Color3.fromRGB(255, 105, 105)
        box.Text = ""
    end
end

button.MouseButton1Click:Connect(redeem)
box.FocusLost:Connect(function(enter)
    if enter then redeem() end
end)

task.spawn(function()
    local token = readToken()
    if token and authenticateToken(token) then
        status.Text = "Saved authorization • Loading..."
        status.TextColor3 = Color3.fromRGB(130, 255, 150)
        task.wait(0.2)
        finish()
    end
end)

repeat task.wait() until unlocked

